package zw.co.opuszim.inbox;
import android.app.Activity;
import android.os.*;
import android.content.*;
import android.net.Uri;
public final class MainActivity extends Activity {
 private static final String HOME="https://opuszim.co.zw/sysadmin/mobile/";
 private boolean launched=false,bound=false;private String destination=HOME;
 private final Binder callback=new Binder(){@Override protected boolean onTransact(int code,Parcel data,Parcel reply,int flags){if(code==INTERFACE_TRANSACTION){reply.writeString("android.support.customtabs.ICustomTabsCallback");return true;}if(reply!=null)reply.writeNoException();return true;}};
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder service){try{Parcel p=Parcel.obtain(),r=Parcel.obtain();p.writeInterfaceToken("android.support.customtabs.ICustomTabsService");p.writeStrongBinder(callback);service.transact(3,p,r,0);r.readException();boolean accepted=r.readInt()!=0;p.recycle();r.recycle();launch(name.getPackageName(),accepted);}catch(Exception e){launch(null,false);}}public void onServiceDisconnected(ComponentName name){}};
 @Override public void onCreate(Bundle state){super.onCreate(state);if(Build.VERSION.SDK_INT>=26){android.app.NotificationChannel channel=new android.app.NotificationChannel("opus_customer_messages_channel_id","Customer messages",android.app.NotificationManager.IMPORTANCE_HIGH);channel.setDescription("New customer enquiries from the Opus Zimbabwe website");getSystemService(android.app.NotificationManager.class).createNotificationChannel(channel);}getWindow().setStatusBarColor(0xff111111);getWindow().setNavigationBarColor(0xff111111);Uri incoming=getIntent().getData();if(incoming!=null&&"https".equals(incoming.getScheme())&&"opuszim.co.zw".equals(incoming.getHost())&&"/sysadmin/mobile/".equals(incoming.getPath()))destination=incoming.toString();
 if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){if(!getPreferences(MODE_PRIVATE).getBoolean("asked-alerts",false)){new android.app.AlertDialog.Builder(this).setTitle("Enable customer alerts").setMessage("Allow OpusChat notifications so new customer messages can reach you even when the app is closed.").setPositiveButton("Continue",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){getPreferences(MODE_PRIVATE).edit().putBoolean("asked-alerts",true).apply();requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},71);}}).setNegativeButton("Not now",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){startInbox();}}).setOnCancelListener(new DialogInterface.OnCancelListener(){public void onCancel(DialogInterface d){startInbox();}}).show();return;}
 new android.app.AlertDialog.Builder(this).setTitle("Notifications are blocked").setMessage("Allow notifications in Android Settings → Apps → OpusChat → Notifications, then enable alerts in OpusChat Settings.").setPositiveButton("Open settings",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){Intent i=new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS);i.putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);finish();}}).setNegativeButton("Open inbox",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){startInbox();}}).setOnCancelListener(new DialogInterface.OnCancelListener(){public void onCancel(DialogInterface d){startInbox();}}).show();return;}
 startInbox();}
 @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==71)startInbox();}
 private void startInbox(){Intent service=new Intent("android.support.customtabs.action.CustomTabsService").setPackage("com.android.chrome");try{bound=bindService(service,connection,Context.BIND_AUTO_CREATE);}catch(Exception ignored){}if(!bound)launch(null,false);else new Handler(Looper.getMainLooper()).postDelayed(new Runnable(){public void run(){if(!launched)launch(null,false);}},2500);}
 private void launch(String browser,boolean session){if(launched||isFinishing())return;launched=true;if(session&&"com.android.chrome".equals(browser))try{new ProviderTokens(this).store(androidx.browser.trusted.Token.create(browser,getPackageManager()));}catch(Exception ignored){}Intent intent=new Intent(Intent.ACTION_VIEW,Uri.parse(destination));if(browser!=null)intent.setPackage(browser);Bundle extras=new Bundle();extras.putBinder("android.support.customtabs.extra.SESSION",session?callback:null);extras.putBoolean("android.support.customtabs.extra.LAUNCH_AS_TRUSTED_WEB_ACTIVITY",session);extras.putInt("android.support.customtabs.extra.TOOLBAR_COLOR",0xff111111);intent.putExtras(extras);try{startActivity(intent);}catch(ActivityNotFoundException e){new android.app.AlertDialog.Builder(this).setTitle("Chrome is needed").setMessage("Install or enable Chrome to open OpusChat securely.").setPositiveButton("Close",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){finish();}}).show();return;}finish();}
 @Override protected void onDestroy(){if(bound){try{unbindService(connection);}catch(Exception ignored){}}super.onDestroy();}
}
